// Cadastro dos clientes: conta do cartão no Conta Azul + regras de lançamento combinadas com a Redacted.
// Para cada cliente novo: adicionar aqui + criar a credencial do Conta Azul dele.
const REGRAS_REDACTED = [                                 // texto da fatura contém -> força esses campos
  { contem: 'UBER', descricao: 'UBER', fornecedor: 'UBER DO BRASIL TECNOLOGIA LTDA.', categoria: 'Transportes' },
  { contem: 'ROLDAO', fornecedor: 'ROLDAO AUTO SERVICO COMERCIO DE ALIMENTO' },
  { contem: 'AMAZON', categoria: 'Despesas a Classificar' }
];
const CLIENTES = {
  'Redacted Matriz': {
    contaCartaoId: '<ID>',
    contaCartaoNome: 'CARTÃO DE CRÉDITO ITAÚ',
    centroCustoPadrao: 'Redacted Matriz',          // sempre (Redacted, 14/10/2026)
    categoriaDuvida: 'Despesas a Classificar',        // na dúvida
    regras: REGRAS_REDACTED
  },
  'Conta de TESTE (fictícia)': {                     // conta de teste do Conta Azul (dados fictícios)
    contaCartaoId: '<ID>',
    contaCartaoNome: 'BANCO TESTE',
    centroCustoPadrao: '',
    categoriaDuvida: 'Bens de Pequeno Valor',
    regras: REGRAS_REDACTED
  }
};
const cliente = $json.cliente || $json.Cliente;
const cfg = CLIENTES[cliente];
if (!cfg) throw new Error('Cliente sem cadastro no robô: ' + cliente);

const bin = $input.item.binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('Nenhum PDF recebido no formulário.');
const buf = await this.helpers.getBinaryDataBuffer($itemIndex, key);

const prompt = [
  'Você é um assistente contábil. Leia a FATURA DE CARTÃO DE CRÉDITO em PDF e devolva SOMENTE um JSON válido (sem markdown).',
  'Regras:',
  '- Liste TODOS os lançamentos de TODOS os cartões (titular e adicionais), nacionais e internacionais, inclusive IOF, anuidade, tarifas, juros, encargos, estornos e créditos.',
  '- NÃO inclua o pagamento da fatura anterior como lançamento; informe o valor dele em pagamento_fatura_anterior.',
  '- NÃO inclua linhas de subtotal/total. Não invente nada; não pule linhas; não junte linhas.',
  '- descricao: copie EXATAMENTE o texto do estabelecimento como impresso, incluindo o número da parcela se vier junto (ex.: "LEROY MERLIN 06/06").',
  '- data: a data da linha exatamente como impressa, no formato DD/MM.',
  '- valor_brl: valor em REAIS (R$), número com ponto decimal. Compras/débitos positivos; estornos/créditos NEGATIVOS.',
  '- COMPRAS INTERNACIONAIS: a fatura mostra, na mesma linha ou logo abaixo, o valor na moeda original (ex.: dólar), a cotação do dólar e o valor em R$. Preencha moeda_original (ex.: "USD"), valor_moeda_original (o valor em dólar), cotacao e valor_brl (o valor em R$, que é aproximadamente valor_moeda_original x cotacao). valor_brl NUNCA é o valor em dólar. Para compras nacionais deixe moeda_original "BRL", valor_moeda_original = valor_brl, cotacao 1.',
  '- O IOF / repasse de IOF de compra internacional é uma linha separada, tipo iof.',
  '- CONFERÊNCIA OBRIGATÓRIA: a soma de todos os valor_brl deve ser igual a total_fatura. Se não bater, releia as linhas (principalmente internacionais e estornos) antes de responder.',
  '- parcela: "NN/NN" se a linha for parcelada (ex.: "06/06"), senão "".',
  '- final_cartao: 4 últimos dígitos do cartão daquela linha. titular: nome impresso do portador daquele cartão.',
  '- tipo: um de compra, estorno, iof, anuidade, tarifa, juros, outro.',
  '- vencimento no formato AAAA-MM-DD. total_fatura = total a pagar desta fatura.',
  'Formato:',
  '{"banco":"","vencimento":"AAAA-MM-DD","total_fatura":0,"pagamento_fatura_anterior":0,"cartoes":[{"final":"","titular":""}],"lancamentos":[{"data":"DD/MM","descricao":"","moeda_original":"BRL","valor_moeda_original":0,"cotacao":1,"valor_brl":0,"parcela":"","final_cartao":"","titular":"","tipo":"compra","internacional":false}]}'
].join('\n');

return { json: {
  cliente,
  modo: String($json.modo || '').toUpperCase().includes('LANÇAR') ? 'lancar' : 'conferir',
  contaCartaoId: cfg.contaCartaoId,
  contaCartaoNome: cfg.contaCartaoNome,
  centroCustoPadrao: cfg.centroCustoPadrao || '',
  categoriaDuvida: cfg.categoriaDuvida || 'Despesas a Classificar',
  regras: cfg.regras || [],
  arquivo: bin[key].fileName || 'fatura.pdf',
  prompt,
  pdf_b64: buf.toString('base64')
} };

const raw = ($json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
if (!raw.trim()) throw new Error('A IA não devolveu nada para esta fatura.');
let f;
try { f = JSON.parse(raw); }
catch (e) { f = JSON.parse(raw.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim()); }

const cfg = $('Config do cliente + PDF').item.json;
const venc = String(f.vencimento || '').slice(0, 10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(venc)) throw new Error('Não achei o vencimento da fatura: ' + f.vencimento);
const vy = Number(venc.slice(0, 4));

// Ano da compra: a fatura só mostra DD/MM. Usa o ano do vencimento; se a data ficar depois do vencimento, é do ano anterior.
// Aceita "24/09", "24/set", "24 SET", "24/09/2026" e "2026-09-24" (a IA às vezes devolve o mês por extenso)
const MESES = { jan: 1, fev: 2, mar: 3, abr: 4, mai: 5, jun: 6, jul: 7, ago: 8, set: 9, out: 10, nov: 11, dez: 12 };
const toISO = txt => {
  const s = String(txt || '').trim().toLowerCase();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/(\d{1,2})\s*[\/\-. ]\s*([a-zç]{3,}|\d{1,2})(?:\s*[\/\-. ]\s*(\d{2,4}))?/);
  if (!m) return '';
  const mesN = /\d/.test(m[2]) ? Number(m[2]) : MESES[m[2].slice(0, 3)];
  if (!mesN) return '';
  const d = m[1].padStart(2, '0'), mo = String(mesN).padStart(2, '0');
  if (m[3]) return (m[3].length === 2 ? '20' + m[3] : m[3]) + '-' + mo + '-' + d;
  let iso = vy + '-' + mo + '-' + d;
  if (iso > venc) iso = (vy - 1) + '-' + mo + '-' + d;
  return iso;
};

const r2 = v => Math.round(Number(v) * 100) / 100;
const cents = v => Math.round(Number(v) * 100);
const totalFatura = r2(f.total_fatura);
// Linhas de R$ 0,00 (ex.: "Repasse de IOF" zerado) são ignoradas
const linhas = (f.lancamentos || []).filter(l => cents(l.valor_brl ?? l.valor) !== 0).map((l, i) => {
  const p = String(l.parcela || '').match(/(\d{1,2})\s*\/\s*(\d{1,2})/);
  const moeda = String(l.moeda_original || 'BRL').toUpperCase();
  return {
    n: i + 1,
    data: toISO(l.data),
    descricao: String(l.descricao || '').trim(),
    valor: r2(l.valor_brl ?? l.valor),
    moeda, cotacao: Number(l.cotacao) || 0, valorCorrigidoPelaCotacao: false,
    parcelaAtual: p ? Number(p[1]) : null,
    parcelaTotal: p ? Number(p[2]) : null,
    final: String(l.final_cartao || '').replace(/\D/g, '').slice(-4),
    titular: String(l.titular || '').trim().toUpperCase(),
    tipo: String(l.tipo || 'compra').toLowerCase(),
    internacional: !!l.internacional || moeda !== 'BRL'
  };
});

// Internacional: a IA às vezes põe o valor em dólar no campo de R$. Se a soma não fecha com o total,
// testa converter (valor x cotação) cada linha internacional e fica com a combinação que fecha o total
// (tolerância de 2 centavos por linha convertida, por arredondamento da cotação).
const somaC = () => linhas.reduce((s, l) => s + cents(l.valor), 0);
const intl = linhas.filter(l => l.internacional && l.cotacao > 1.5 && l.valor > 0);
if (somaC() !== cents(totalFatura) && intl.length && intl.length <= 10) {
  const base = somaC() - intl.reduce((s, l) => s + cents(l.valor), 0);
  let melhor = null;
  for (let mask = 1; mask < (1 << intl.length); mask++) {
    const vals = intl.map((l, k) => (mask >> k) & 1 ? r2(l.valor * l.cotacao) : l.valor);
    const dif = Math.abs(base + vals.reduce((s, v) => s + cents(v), 0) - cents(totalFatura));
    const nConv = intl.filter((l, k) => (mask >> k) & 1).length;
    if (dif <= 2 * nConv && (!melhor || dif < melhor.dif)) melhor = { mask, vals, dif };
  }
  if (melhor) intl.forEach((l, k) => { if ((melhor.mask >> k) & 1) { l.valor = melhor.vals[k]; l.valorCorrigidoPelaCotacao = true; } });
}

const soma = r2(linhas.reduce((s, l) => s + l.valor, 0));
const addDays = (iso, n) => { const d = new Date(iso + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };

return { json: {
  cliente: cfg.cliente,
  contaCartaoId: cfg.contaCartaoId,
  contaCartaoNome: cfg.contaCartaoNome,
  arquivo: cfg.arquivo,
  banco: f.banco || '',
  vencimento: venc,
  buscaDe: addDays(venc, -5),
  buscaAte: addDays(venc, 5),
  totalFatura,
  pagamentoAnterior: Number(f.pagamento_fatura_anterior) || 0,
  somaLinhas: soma,
  cartoes: f.cartoes || [],
  linhas
} };

const F = $('Organizar linhas da fatura').first().json;
const CFG = $('Config do cliente + PDF').first().json;
const resp = $('Conta Azul - despesas do cartão (só leitura)').first().json;
const mapCA = c => ({
  id: c.id,
  descricao: c.descricao || '',
  valor: Math.round(Number(c.total) * 100) / 100,
  competencia: String(c.data_competencia || '').slice(0, 10),
  vencimento: String(c.data_vencimento || '').slice(0, 10),
  categoria: (c.categorias || []).map(x => x.nome).join(', '),
  cats: c.categorias || [],
  centroCusto: (c.centros_de_custo || c.centros_custo || []).map(x => x.nome).join(', '),
  ccs: c.centros_de_custo || c.centros_custo || [],
  fornecedor: c.fornecedor?.nome || '',
  fornecedorId: c.fornecedor?.id || '',
  usado: false
});
const ca = (resp.itens || []).map(mapCA);
// Histórico de 12 meses do cartão, SEM a fatura atual
const hist = $('Conta Azul - histórico do cartão (só leitura)').all().flatMap(i => i.json.itens || []).map(mapCA).filter(c => c.vencimento && c.vencimento < F.buscaDe);

// Dicionários nome -> id (categoria, fornecedor, centro de custo)
const catId = {}, fornId = {}, ccId = {};
const K = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, '');
[...hist, ...ca].forEach(c => {
  c.cats.forEach(x => { if (x.id && x.nome) catId[K(x.nome)] = x.id; });
  c.ccs.forEach(x => { if (x.id && x.nome) ccId[K(x.nome)] = x.id; });
  if (c.fornecedorId && c.fornecedor) fornId[K(c.fornecedor)] = c.fornecedorId;
});
try { ($('Conta Azul - categorias').first().json.itens || []).forEach(x => { if (x.id && x.nome && !catId[K(x.nome)]) catId[K(x.nome)] = x.id; }); } catch (e) {}
try { const cc = $('Conta Azul - centros de custo').first().json; (cc.itens || cc.items || []).forEach(x => { if (x.id && x.nome && !ccId[K(x.nome)]) ccId[K(x.nome)] = x.id; }); } catch (e) {}

// Nome do portador como a Redacted escreve (ex.: "SOLANGE MORAIS TEIXEIRA"), por final do cartão
const nomePorFinal = {};
[...hist, ...ca].forEach(c => { const m = c.descricao.toUpperCase().match(/-\s*([A-ZÀ-Ü][A-ZÀ-Ü ]+?)\s*-\s*FINAL\s*(\d{4})/); if (m) nomePorFinal[m[2]] = m[1].trim(); });

const nomes = new Set(['IDENTIFICAR', 'DESPESA', 'FINAL', 'DESPESAS', 'CLASSIFICAR', 'PENDENTE']);
(F.cartoes || []).forEach(c => String(c.titular || '').toUpperCase().split(/\s+/).forEach(t => nomes.add(t)));
F.linhas.forEach(l => l.titular.split(/\s+/).forEach(t => nomes.add(t)));
Object.values(nomePorFinal).forEach(n => n.split(/\s+/).forEach(t => nomes.add(t)));
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
const compact = s => norm(s).replace(/\s+/g, '');
const toks = s => norm(s).split(' ').filter(t => t.length >= 3 && !nomes.has(t) && !/^\d+$/.test(t));
const comum = (a, b) => { const B = new Set(toks(b)); return toks(a).filter(t => B.has(t)).length; };
const cents = v => Math.round(Number(v) * 100);
const brl = v => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const br = iso => iso ? iso.split('-').reverse().join('/') : '';

const linhas = F.linhas.map(l => ({ ...l, status: '', ca: null, descConfere: null }));

// 1) Mesmo valor (prefere mesma data de compra e nome parecido)
[...linhas].filter(l => l.valor > 0).sort((a, b) => b.valor - a.valor).forEach(l => {
  let best = null, bestScore = -1;
  for (const c of ca) {
    if (c.usado || cents(c.valor) !== cents(l.valor)) continue;
    const s = (c.competencia === l.data ? 4 : 0) + comum(l.descricao, c.descricao + ' ' + c.fornecedor) + (c.descricao.includes(l.final) ? 1 : 0);
    if (s > bestScore) { best = c; bestScore = s; }
  }
  if (best) { best.usado = true; l.ca = best; l.status = best.competencia === l.data ? 'OK' : 'OK_DATA'; }
});

// 2) Valor diferente: mesmo nome, valor próximo
linhas.filter(l => !l.ca && l.valor > 0).forEach(l => {
  let best = null, bestScore = 0;
  for (const c of ca) {
    if (c.usado) continue;
    const s = comum(l.descricao, c.descricao + ' ' + c.fornecedor);
    const dif = Math.abs(c.valor - l.valor);
    if (s >= 1 && dif <= Math.max(1, l.valor * 0.15) && s > bestScore) { best = c; bestScore = s; }
  }
  if (best) { best.usado = true; l.ca = best; l.status = 'VALOR_DIF'; }
});

// 2b) Uma linha da fatura lançada em várias partes no CA (ex.: repasse de IOF separado por compra)
linhas.filter(l => !l.ca && l.valor > 0).forEach(l => {
  const cands = ca.filter(c => !c.usado && (comum(l.descricao, c.descricao + ' ' + c.fornecedor) >= 1 || (l.tipo === 'iof' && norm(c.descricao).includes('IOF'))));
  if (cands.length < 2) return;
  const soma = cands.reduce((s, c) => s + cents(c.valor), 0);
  if (soma !== cents(l.valor)) return;
  cands.forEach(c => { c.usado = true; });
  l.ca = { descricao: cands.map(c => c.descricao).join(' + '), valor: soma / 100, competencia: cands[0].competencia, categoria: [...new Set(cands.map(c => c.categoria))].join(', '), fornecedor: '', centroCusto: '', dividido: true };
  l.status = 'OK_DIVIDIDO';
});

// 3) Estorno x cobrança de mesmo valor na própria fatura que não estão no CA -> se anulam
linhas.filter(l => !l.ca && l.valor < 0).forEach(e => {
  const par = linhas.find(x => !x.ca && !x.status && x.valor > 0 && cents(x.valor) === -cents(e.valor));
  if (par) { e.status = 'ANULA'; par.status = 'ANULA'; }
});
linhas.filter(l => !l.status).forEach(l => {
  if (l.valor < 0) l.status = 'ESTORNO';
  else if (l.parcelaAtual && l.parcelaAtual > 1) l.status = 'FALTA_PARCELA_ANTIGA';
  else l.status = 'FALTA';
});

linhas.forEach(l => { if (l.ca) l.descConfere = compact(l.ca.descricao).includes(compact(l.descricao)); });
const sobras = ca.filter(c => !c.usado);

// ---------- SUGESTÃO DE LANÇAMENTO (aprende só com meses anteriores + regras da Redacted) ----------
const semParcela = s => String(s).replace(/\d{1,2}\s*\/\s*\d{1,2}/g, ' ');
const pontua = (l, h) => {
  const a = semParcela(l.descricao), b = semParcela(h.descricao);
  let s = comum(a, b);
  const ca_ = compact(a), cb = compact(b);
  s += toks(b).filter(t => t.length >= 4 && ca_.includes(t) && !toks(a).includes(t)).length;
  s += toks(a).filter(t => t.length >= 4 && cb.includes(t) && !toks(b).includes(t)).length;
  return s;
};
const nomeFornecedorNovo = d => String(d).replace(/\d{1,2}\s*\/\s*\d{1,2}/g, ' ').replace(/-\s*CT\b.*$/i, ' ').replace(/^[A-Z]{1,4}\s*\*\s*/i, '').replace(/\*/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase() || String(d).toUpperCase();
const moda = (lista, k) => { const c = new Map(); lista.forEach(h => c.set(h[k], (c.get(h[k]) || 0) + 1)); let m = null; for (const [v, n] of c) if (!m || n > m[1]) m = [v, n]; return m ? m[0] : ''; };
const sugerir = l => {
  const nome = nomePorFinal[l.final] || l.titular;
  const prefixo = (l.parcelaAtual === 1 && l.parcelaTotal > 1) ? ('1/' + l.parcelaTotal + ' - ') : '';
  const padrao = prefixo + 'IDENTIFICAR DESPESA - ' + l.descricao + ' - ' + nome + ' - FINAL ' + l.final;
  let best = [], bestS = 0;
  for (const h of hist) {
    let s = pontua(l, h);
    if (!s) continue;
    if (l.parcelaTotal && cents(h.valor) === cents(l.valor)) s += 3;
    if (s > bestS) { bestS = s; best = [h]; } else if (s === bestS) best.push(h);
  }
  let r;
  if (!best.length) {
    r = { fonte: 'novo (sem histórico)', descricao: padrao, categoria: CFG.categoriaDuvida, fornecedor: nomeFornecedorNovo(l.descricao) };
  } else {
    best.sort((a, b) => b.vencimento.localeCompare(a.vencimento));
    const mesRecente = best[0].vencimento.slice(0, 7);
    const doMes = best.filter(h => h.vencimento.slice(0, 7) === mesRecente);
    const modelo = moda(doMes, 'descricao');
    let desc;
    if (/IDENTIFICAR\s+DESPESA/i.test(modelo)) desc = padrao;
    else desc = l.parcelaTotal ? modelo.replace(/(\d{1,2})\s*\/\s*(\d{1,2})/, (m, a) => { const p = n => a.length === 2 ? String(n).padStart(2, '0') : String(n); return p(l.parcelaAtual) + '/' + p(l.parcelaTotal); }) : modelo;
    if (prefixo && !desc.startsWith(prefixo)) desc = prefixo + desc;
    const catsMes = [...new Set(doMes.map(h => h.categoria))];
    const categoria = catsMes.length === 1 ? catsMes[0] : CFG.categoriaDuvida;
    let fornecedor = moda(doMes.filter(h => h.fornecedor), 'fornecedor') || moda(best.filter(h => h.fornecedor), 'fornecedor');
    if (!fornecedor) fornecedor = nomeFornecedorNovo(l.descricao);
    r = { fonte: 'histórico (' + best.length + ')', descricao: desc, categoria: categoria || CFG.categoriaDuvida, fornecedor };
  }
  for (const rg of (CFG.regras || [])) {
    if (!compact(l.descricao).includes(compact(rg.contem))) continue;
    if (rg.descricao) r.descricao = prefixo + rg.descricao + ' - ' + nome + ' - FINAL ' + l.final;
    if (rg.fornecedor) r.fornecedor = rg.fornecedor;
    if (rg.categoria) r.categoria = rg.categoria;
    r.fonte += ' + regra ' + rg.contem;
  }
  r.centroCusto = CFG.centroCustoPadrao || '';
  if (!catId[K(r.categoria)]) r.categoria = CFG.categoriaDuvida;
  r.categoriaId = catId[K(r.categoria)] || '';
  r.fornecedorId = fornId[K(r.fornecedor)] || '';
  r.centroCustoId = ccId[K(r.centroCusto)] || '';
  if (r.centroCusto && !r.centroCustoId) r.centroCusto = '';
  return r;
};
const igual = (a, b) => compact(a) === compact(b);
const sim = linhas.filter(l => l.valor > 0).map(l => {
  const r = sugerir(l);
  const real = l.ca && !l.ca.dividido ? l.ca : null;
  const ok = real ? {
    descricao: igual(r.descricao, real.descricao), categoria: igual(r.categoria, real.categoria), fornecedor: igual(r.fornecedor, real.fornecedor),
    centroCusto: igual(r.centroCusto, real.centroCusto), competencia: l.data === real.competencia
  } : null;
  return { n: l.n, status: l.status, fatura: l.descricao, valor: l.valor, data: l.data, final: l.final, robo: { ...r, competencia: l.data || F.vencimento, vencimento: F.vencimento }, Redacted: real ? { descricao: real.descricao, categoria: real.categoria, fornecedor: real.fornecedor, centroCusto: real.centroCusto, competencia: real.competencia } : null, ok };
});
const comp = sim.filter(s => s.ok);
const pct = f => comp.length ? Math.round(100 * comp.filter(f).length / comp.length) : 0;
const simResumo = {
  linhas: sim.length, comparadas: comp.length, historico: hist.length,
  mesesHistorico: [...new Set(hist.map(h => h.vencimento.slice(0, 7)))].sort(),
  descricao: pct(s => s.ok.descricao), categoria: pct(s => s.ok.categoria), fornecedor: pct(s => s.ok.fornecedor),
  centroCusto: pct(s => s.ok.centroCusto), competencia: pct(s => s.ok.competencia),
  lancamentoCerto: pct(s => s.ok.categoria && s.ok.fornecedor && s.ok.competencia),
  semHistorico: sim.filter(s => s.robo.fonte.startsWith('novo')).length
};

// ---------- O QUE O ROBÔ VAI LANÇAR (só linhas que NÃO estão no CA) ----------
const aLancar = sim.filter(s => ['FALTA', 'FALTA_PARCELA_ANTIGA'].includes(s.status)).map(s => ({
  n: s.n, fatura: s.fatura, valor: s.valor,
  descricao: s.robo.descricao, categoria: s.robo.categoria, categoriaId: s.robo.categoriaId,
  fornecedor: s.robo.fornecedor, fornecedorId: s.robo.fornecedorId,
  centroCusto: s.robo.centroCusto, centroCustoId: s.robo.centroCustoId,
  competencia: s.robo.competencia, vencimento: F.vencimento, contaCartaoId: F.contaCartaoId,
  referencia: 'robo-cartao:' + s.final + ':' + F.vencimento + ':' + s.n + ':' + cents(s.valor)
}));
const bloqueios = [];
if (!(cents(F.somaLinhas) === cents(F.totalFatura))) bloqueios.push('A leitura da IA não fechou com o total da fatura.');
if (aLancar.some(a => !a.categoriaId)) bloqueios.push('Não achei o ID da categoria "' + CFG.categoriaDuvida + '" no Conta Azul.');
if (aLancar.length > 150) bloqueios.push('Mais de 150 lançamentos de uma vez (limite de segurança).');
const podeLancar = CFG.modo === 'lancar' && aLancar.length > 0 && bloqueios.length === 0;

// Alertas de qualidade nos lançamentos do CA
const alertas = [];
const aClass = ca.filter(c => norm(c.categoria).includes('CLASSIFICAR') || !c.categoria);
if (aClass.length) alertas.push({ tipo: 'Categoria pendente', texto: aClass.length + ' lançamento(s) em "Despesas a Classificar" (' + brl(aClass.reduce((s, c) => s + c.valor, 0)) + ').', itens: aClass.map(c => c.descricao + ' — ' + brl(c.valor)) });
const semForn = ca.filter(c => !c.fornecedor);
if (semForn.length) alertas.push({ tipo: 'Fornecedor vazio', texto: semForn.length + ' lançamento(s) sem fornecedor.', itens: semForn.map(c => c.descricao + ' — ' + brl(c.valor)) });
const futuras = ca.filter(c => c.competencia && c.competencia > F.vencimento);
if (futuras.length) alertas.push({ tipo: 'Competência futura', texto: 'Competência depois do vencimento da fatura (provável erro de digitação).', itens: futuras.map(c => c.descricao + ' — competência ' + br(c.competencia)) });
const dataDif = linhas.filter(l => l.status === 'OK_DATA');
if (dataDif.length) alertas.push({ tipo: 'Data diferente', texto: 'Competência no CA diferente da data da compra na fatura.', itens: dataDif.map(l => l.descricao + ' — fatura ' + br(l.data) + ' / CA ' + br(l.ca.competencia)) });
const porNome = {};
ca.forEach(c => { const k = toks(c.descricao).join(' '); if (!k) return; (porNome[k] ||= new Set()).add(c.categoria || '(sem)'); });
const incons = Object.entries(porNome).filter(([k, s]) => s.size > 1);
if (incons.length) alertas.push({ tipo: 'Categoria inconsistente', texto: 'Mesma despesa lançada em categorias diferentes.', itens: incons.map(([k, s]) => k + ': ' + [...s].join(' x ')) });

const somaCA = Math.round(ca.reduce((s, c) => s + c.valor, 0) * 100) / 100;
const cont = s => linhas.filter(l => l.status === s).length;
const r = {
  cliente: F.cliente, arquivo: F.arquivo, banco: F.banco, vencimento: F.vencimento, modo: CFG.modo,
  totalFatura: F.totalFatura, somaLinhas: F.somaLinhas, somaCA,
  linhasFatura: linhas.length, lancamentosCA: ca.length, itensTotaisAPI: resp.itens_totais,
  ok: cont('OK') + cont('OK_DATA') + cont('OK_DIVIDIDO'), valorDif: cont('VALOR_DIF'), falta: cont('FALTA'), faltaParcelaAntiga: cont('FALTA_PARCELA_ANTIGA'),
  anula: cont('ANULA'), estorno: cont('ESTORNO'), soNoCA: sobras.length,
  simulacao: simResumo, aLancar: aLancar.length, bloqueios
};
r.leituraIA_ok = cents(r.somaLinhas) === cents(r.totalFatura);
r.fechou = r.valorDif === 0 && r.falta === 0 && r.faltaParcelaAntiga === 0 && r.estorno === 0 && r.soNoCA === 0;

// ---------- Relatório HTML ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ROT = {
  OK: ['Confere', '#1b7f3b'], OK_DATA: ['Confere (data diferente)', '#b26a00'], OK_DIVIDIDO: ['Confere (lançado em partes no CA)', '#1b7f3b'], VALOR_DIF: ['Valor diferente', '#c0392b'],
  FALTA: ['Falta no CA', '#c0392b'], FALTA_PARCELA_ANTIGA: ['Parcela antiga faltando', '#c0392b'],
  ANULA: ['Cobrança e estorno se anulam', '#666'], ESTORNO: ['Estorno (ver manual)', '#b26a00']
};
const td = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;vertical-align:top"';
const tdr = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;text-align:right;white-space:nowrap;vertical-align:top"';
const th = 'style="padding:4px 6px;border-bottom:2px solid #333;font-size:12px;text-align:left"';
const badge = s => '<span style="color:' + ROT[s][1] + ';font-weight:bold">' + ROT[s][0] + '</span>';
const card = (t, v, cor) => '<div style="display:inline-block;margin:4px;padding:8px 12px;border:1px solid #ccc;border-radius:6px;min-width:120px"><div style="font-size:11px;color:#555">' + t + '</div><div style="font-size:18px;font-weight:bold;color:' + (cor || '#222') + '">' + v + '</div></div>';
const corPct = p => p >= 95 ? '#1b7f3b' : p >= 80 ? '#b26a00' : '#c0392b';

let h = '<div style="font-family:Arial,sans-serif;text-align:left;max-width:1200px;margin:auto">';
h += '<h2 style="margin:4px 0">' + esc(F.cliente) + ' — fatura venc. ' + br(F.vencimento) + '</h2>';
h += '<p style="margin:2px 0;font-size:13px">' + (r.fechou ? '<b style="color:#1b7f3b">✅ Fatura FECHADA: tudo o que está na fatura está no Conta Azul.</b>' : '<b style="color:#c0392b">⚠️ Há diferenças — veja abaixo.</b>') + '</p>';
if (CFG.modo === 'lancar' && !podeLancar) h += '<p style="color:#c0392b;font-size:13px"><b>Nada foi lançado.</b> ' + (aLancar.length ? esc(bloqueios.join(' ')) : 'Não há nada faltando no Conta Azul.') + '</p>';
h += '<div>' + card('Total da fatura', brl(r.totalFatura)) + card('Soma lida pela IA', brl(r.somaLinhas), r.leituraIA_ok ? '#1b7f3b' : '#c0392b') + card('Soma no Conta Azul', brl(r.somaCA), cents(r.somaCA) === cents(r.totalFatura) ? '#1b7f3b' : '#b26a00') + '</div>';
h += '<div>' + card('Linhas na fatura', r.linhasFatura) + card('Conferem', r.ok, '#1b7f3b') + card('Faltam no CA', r.falta + r.faltaParcelaAntiga, (r.falta + r.faltaParcelaAntiga) ? '#c0392b' : '#1b7f3b') + card('Valor diferente', r.valorDif, r.valorDif ? '#c0392b' : '#1b7f3b') + card('Só no CA', r.soNoCA, r.soNoCA ? '#c0392b' : '#1b7f3b') + '</div>';
if (!r.leituraIA_ok) h += '<p style="color:#c0392b;font-size:12px">A soma das linhas lidas pela IA não bate com o total da fatura (diferença ' + brl(r.somaLinhas - r.totalFatura) + '). Pode ter linha lida errado.</p>';
if (r.itensTotaisAPI > 100) h += '<p style="color:#c0392b;font-size:12px">Atenção: o CA tem ' + r.itensTotaisAPI + ' lançamentos nesse vencimento e só os 100 primeiros foram lidos.</p>';

if (aLancar.length) {
  h += '<h3 style="margin-top:18px">📝 ' + (podeLancar ? 'Lançamentos enviados ao Conta Azul' : 'O robô lançaria (faltam no Conta Azul)') + ': ' + aLancar.length + '</h3><table style="border-collapse:collapse;width:100%"><tr><th ' + th + '>#</th><th ' + th + '>Descrição</th><th ' + th + '>Valor</th><th ' + th + '>Categoria</th><th ' + th + '>Fornecedor</th><th ' + th + '>Centro de custo</th><th ' + th + '>Competência</th><th ' + th + '>Vencimento</th></tr>';
  aLancar.forEach(a => { h += '<tr><td ' + td + '>' + a.n + '</td><td ' + td + '>' + esc(a.descricao) + '</td><td ' + tdr + '>' + brl(a.valor) + '</td><td ' + td + '>' + esc(a.categoria) + '</td><td ' + td + '>' + esc(a.fornecedor) + (a.fornecedorId ? '' : ' <span style="color:#b26a00">(novo)</span>') + '</td><td ' + td + '>' + esc(a.centroCusto) + '</td><td ' + td + '>' + br(a.competencia) + '</td><td ' + td + '>' + br(a.vencimento) + '</td></tr>'; });
  h += '</table>';
}

h += '<h3 style="margin-top:18px">🤖 Simulação: o que o robô lançaria x o que está no Conta Azul</h3>';
h += '<p style="font-size:12px;margin:2px 0">Aprendeu com ' + simResumo.historico + ' lançamentos de faturas anteriores (' + simResumo.mesesHistorico.map(m => m.split('-').reverse().join('/')).join(', ') + ') + regras combinadas. Em vermelho: o que está diferente no Conta Azul.</p>';
h += '<div>' + card('Lançamento certo (categoria + fornecedor + data)', simResumo.lancamentoCerto + '%', corPct(simResumo.lancamentoCerto)) + card('Categoria igual', simResumo.categoria + '%', corPct(simResumo.categoria)) + card('Fornecedor igual', simResumo.fornecedor + '%', corPct(simResumo.fornecedor)) + card('Data igual', simResumo.competencia + '%', corPct(simResumo.competencia)) + card('Descrição idêntica', simResumo.descricao + '%', corPct(simResumo.descricao)) + card('Empresas novas', simResumo.semHistorico) + '</div>';
const cel = (rob, lai, ok) => esc(rob || '—') + (ok === false ? '<div style="color:#c0392b">No CA: ' + esc(lai || '(vazio)') + '</div>' : '');
h += '<table style="border-collapse:collapse;width:100%"><tr><th ' + th + '>#</th><th ' + th + '>Fatura</th><th ' + th + '>Valor</th><th ' + th + '>Descrição (robô)</th><th ' + th + '>Categoria</th><th ' + th + '>Fornecedor</th><th ' + th + '>Centro de custo</th><th ' + th + '>Competência</th><th ' + th + '>Resultado</th></tr>';
sim.forEach(s => {
  const o = s.ok || {};
  const L = s.Redacted || {};
  const res = !s.ok ? '<span style="color:#b26a00">' + (['FALTA', 'FALTA_PARCELA_ANTIGA'].includes(s.status) ? 'Falta no CA' : 'Lançado em partes') + '</span>' : (o.categoria && o.fornecedor && o.competencia) ? '<span style="color:#1b7f3b;font-weight:bold">✔ certo</span>' : '<span style="color:#c0392b">✘ diferente</span>';
  h += '<tr><td ' + td + '>' + s.n + '</td><td ' + td + '>' + esc(s.fatura) + '<div style="color:#888">' + esc(s.robo.fonte) + '</div></td><td ' + tdr + '>' + brl(s.valor) + '</td><td ' + td + '>' + cel(s.robo.descricao, L.descricao, o.descricao) + '</td><td ' + td + '>' + cel(s.robo.categoria, L.categoria, o.categoria) + '</td><td ' + td + '>' + cel(s.robo.fornecedor, L.fornecedor, o.fornecedor) + '</td><td ' + td + '>' + cel(s.robo.centroCusto, L.centroCusto, o.centroCusto) + '</td><td ' + td + '>' + cel(br(s.robo.competencia), br(L.competencia), o.competencia) + '</td><td ' + td + '>' + res + '</td></tr>';
});
h += '</table>';

const probs = linhas.filter(l => !['OK', 'OK_DIVIDIDO', 'ANULA'].includes(l.status));
if (probs.length || sobras.length) {
  h += '<h3>Diferenças fatura x Conta Azul</h3><table style="border-collapse:collapse;width:100%"><tr><th ' + th + '>Situação</th><th ' + th + '>Data</th><th ' + th + '>Fatura</th><th ' + th + '>Valor fatura</th><th ' + th + '>No Conta Azul</th><th ' + th + '>Valor CA</th></tr>';
  probs.forEach(l => { h += '<tr><td ' + td + '>' + badge(l.status) + '</td><td ' + td + '>' + br(l.data) + '</td><td ' + td + '>' + esc(l.descricao) + ' <span style="color:#888">(final ' + esc(l.final) + ')</span></td><td ' + tdr + '>' + brl(l.valor) + '</td><td ' + td + '>' + esc(l.ca ? l.ca.descricao : '—') + '</td><td ' + tdr + '>' + (l.ca ? brl(l.ca.valor) : '—') + '</td></tr>'; });
  sobras.forEach(c => { h += '<tr><td ' + td + '><span style="color:#c0392b;font-weight:bold">Só no CA (não está na fatura)</span></td><td ' + td + '>' + br(c.competencia) + '</td><td ' + td + '>—</td><td ' + tdr + '>—</td><td ' + td + '>' + esc(c.descricao) + '</td><td ' + tdr + '>' + brl(c.valor) + '</td></tr>'; });
  h += '</table>';
}

if (alertas.length) {
  h += '<h3>Alertas de qualidade (lançamentos do CA)</h3>';
  alertas.forEach(a => { h += '<p style="margin:6px 0 2px;font-size:13px"><b>' + esc(a.tipo) + ':</b> ' + esc(a.texto) + '</p><ul style="margin:0;font-size:12px">' + a.itens.slice(0, 30).map(i => '<li>' + esc(i) + '</li>').join('') + '</ul>'; });
}
h += '<p style="font-size:11px;color:#888">' + (podeLancar ? 'O robô só CRIA lançamentos que faltam. Nunca apaga nem altera nada.' : 'Modo conferência: o robô só leu dados. Nada foi alterado no Conta Azul.') + '</p></div>';

return [{ json: { resumo: r, podeLancar, aLancar, alertas, linhas, sobras, simulacao: sim, html: h } }];

// Um item por fornecedor (evita cadastrar o mesmo fornecedor novo duas vezes)
const a = $input.first().json.aLancar || [];
