  (g[k] ||= { fornecedor: x.fornecedor, fornecedorId: x.fornecedorId, lancamentos: [] }).lancamentos.push(x);
});
return Object.values(g).map(v => ({ json: v }));

const g = $('Agrupar por fornecedor').item.json;
const K = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, '');
if (g.fornecedorId) return { json: { ...g, precisaCriar: false } };
const lista = $json.itens || $json.items || $json.data || $json.content || [];
const alvo = K(g.fornecedor);
const achou = lista.find(p => K(p.nome) === alvo || K(p.nome_fantasia) === alvo) || lista.find(p => alvo.length >= 5 && (K(p.nome).startsWith(alvo) || K(p.nome_fantasia).startsWith(alvo)));
return { json: { ...g, fornecedorId: achou?.id || '', fornecedorEncontrado: achou?.nome || '', precisaCriar: !achou } };

const g = $('Escolher fornecedor').item.json;
