const base = $('Comparar fatura x Conta Azul').first().json;
const todos = $('Montar lançamentos').all().map(i => i.json);
const filtrados = $('Só os que podem ser criados').all();
const enviados = $input.all().map((it, i) => {
  const a = filtrados[i].json;
  const st = it.json.statusCode;
  const body = it.json.body || {};
  const ok = st >= 200 && st < 300;
  return { ...a, ok, idCriado: body.id || '', erro: ok ? '' : ('HTTP ' + st + ': ' + JSON.stringify(body).slice(0, 300)) };
});
const pulados = todos.filter(a => a.pular).map(a => ({ ...a, ok: false }));
const res = [...enviados, ...pulados].sort((a, b) => a.n - b.n);
const okN = res.filter(r => r.ok).length;
const soma = res.filter(r => r.ok).reduce((s, r) => s + r.valor, 0);
const brl = v => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const td = 'style="padding:4px 6px;border-bottom:1px solid #ddd;font-size:12px;vertical-align:top"';
const th = 'style="padding:4px 6px;border-bottom:2px solid #333;font-size:12px;text-align:left"';
let h = '<div style="font-family:Arial,sans-serif;text-align:left;max-width:1200px;margin:auto">';
h += '<h2 style="margin:4px 0">' + (okN === res.length ? '✅' : '⚠️') + ' Lançamento automático: ' + okN + ' de ' + res.length + ' criados no Conta Azul (' + brl(soma) + ')</h2>';
const novos = [...new Set(res.filter(r => r.ok && r.fornecedorCriado).map(r => r.fornecedor))];
if (novos.length) h += '<p style="font-size:13px">Fornecedores cadastrados agora: ' + esc(novos.join(', ')) + '</p>';
h += '<table style="border-collapse:collapse;width:100%"><tr><th ' + th + '>#</th><th ' + th + '>Descrição</th><th ' + th + '>Valor</th><th ' + th + '>Categoria</th><th ' + th + '>Fornecedor</th><th ' + th + '>Resultado</th></tr>';
res.forEach(r => { h += '<tr><td ' + td + '>' + r.n + '</td><td ' + td + '>' + esc(r.descricao) + '</td><td ' + td + '>' + brl(r.valor) + '</td><td ' + td + '>' + esc(r.categoria) + '</td><td ' + td + '>' + esc(r.fornecedor) + '</td><td ' + td + '>' + (r.ok ? '<span style="color:#1b7f3b;font-weight:bold">✔ criado</span>' : '<span style="color:#c0392b">✘ ' + esc(r.erro) + '</span>') + '</td></tr>'; });
h += '</table><hr style="margin:20px 0"></div>';
return [{ json: { criados: okN, total: res.length, resultado: res, html: h + base.html } }];
